<?php
require_once __DIR__.'/booking_engine.php';requireRole(['customer']);$db=bdb();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
$_SESSION['tm_booking_csrf']??=bin2hex(random_bytes(32));$error='';$success='';$turf=null;
try{$turf=tmTurf($db,$id);}catch(Throwable $e){$error=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'&&$turf){try{if(!hash_equals($_SESSION['tm_booking_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Session expired. Refresh the page.');$result=tmBook($db,$id,(string)($_POST['date']??''),(string)($_POST['start']??''),(string)($_POST['end']??''),(string)($_POST['phone']??''));$success='Booking #'.$result['group_id'].' submitted for approval. Total: Rs. '.number_format($result['quote']['total'],2);}catch(Throwable $e){$error=$e->getMessage();}}
bookingHead('Book Turf');
?><main class="wrap"><a class="btn btn-ghost" href="turfs.php">← Explore Turfs</a><?php if(!$turf):?><div class="alert"><?=esc($error)?></div><?php else:?><div class="detail"><section><img class="detail-photo" src="../assets/images/<?=esc(sportImage((string)$turf['sport']))?>" alt="<?=esc($turf['name'])?>"><div class="panel"><span class="chip"><?=esc(ucfirst((string)$turf['sport']))?></span><h1><?=esc($turf['name'])?></h1><p>📍 <?=esc($turf['location']?:$turf['facility'])?></p><h3>About this turf</h3><p><?=esc($turf['description']?:'Play your next game at this sports venue.')?></p><div class="muted">Base rate from Rs. <?=number_format((float)$turf['price'],2)?> / hour. Actual rate depends on your date and time.</div></div></section><aside class="panel"><h2>Book this turf</h2><p class="muted">See your exact price before submitting.</p><?php if($error):?><div class="alert"><?=esc($error)?></div><?php endif;?><?php if($success):?><div class="success"><?=esc($success)?></div><a class="btn" href="my-bookings.php">View My Bookings</a><?php endif;?><form id="booking-form" method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['tm_booking_csrf'])?>"><label>Booking date<input name="date" type="date" min="<?=date('Y-m-d')?>" required></label><div class="two"><label>Start time<input name="start" type="time" step="60" required></label><label>End time<input name="end" type="time" step="60" required></label></div><label>Contact phone<input name="phone" type="tel" maxlength="30" placeholder="03xx-xxxxxxx" required></label><div id="quote" class="quote" aria-live="polite">Choose a date and times to calculate your price.</div><button id="book-btn" class="btn wide" type="submit" disabled>Confirm booking request</button></form><div class="action-row"><a class="btn btn-outline" href="turfs.php">Explore Turfs</a><a class="btn btn-outline" href="my-bookings.php">View My Bookings</a></div></aside></div>
<script>
(()=>{const f=document.getElementById('booking-form'),q=document.getElementById('quote'),b=document.getElementById('book-btn');let seq=0;async function update(){const n=++seq;b.disabled=true;const fd=new FormData(f);if(!fd.get('date')||!fd.get('start')||!fd.get('end')){q.textContent='Choose a date and times to calculate your price.';return;}fd.append('turf_id',<?=json_encode($id)?>);q.textContent='Checking availability and pricing…';try{const res=await fetch('booking-quote.php',{method:'POST',body:fd,credentials:'same-origin'});const data=await res.json();if(n!==seq)return;if(!data.ok)throw new Error(data.error||'Unable to calculate price.');const x=data.quote;const money=v=>'Rs. '+Number(v).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});q.replaceChildren();const h=document.createElement('strong');h.textContent='Total: '+money(x.total);q.append(h);for(const item of x.items){const p=document.createElement('div');p.className='quote-line';p.textContent=item.start+' → '+item.end+' | '+money(item.rate)+'/hour | '+money(item.amount)+' ('+item.rule+')';q.append(p);}const info=document.createElement('small');info.textContent=x.matched_rules+' matching active rules; '+x.active_rules+' active rules on this turf.';q.append(info);b.disabled=false;}catch(e){if(n!==seq)return;q.textContent=e.message;}}f.querySelectorAll('input').forEach(i=>i.addEventListener('change',update));f.addEventListener('submit',e=>{if(b.disabled)e.preventDefault();});})();
</script><?php endif;?></main><?php bookingFoot(); ?>
